def count_vowels(s):
    vowels = set('aeiouAEIOU')
    count = 0
    for i in range(len(s)):
        if s[i] in vowels:
            left = s[i - 1] if i > 0 else None
            right = s[i + 1] if i < len(s) - 1 else None
            if left in vowels and right in vowels:
                count += 1
    return count
